      "ကျာ်ဇၞော်မွဲမွဲ၊ အ္စာမွဲမွဲ ဂွံက္လိဂွံကွး တုပ်သၟဟ်ကဵု တၠဂုဏ်အ္စာဉာဏပါလဂှ်လေဝ် ဟွဲလောဲသွာပုဟ် အဲထေင်ကေတ်ရ",
