      "တုဲပၠန် ကဵုကေတ် ရေင်သကအ် နဒဒှ်တၟာဲတဲ ဟွံသေင်မ္ဂး နကဵုသက်သဳမွဲမွဲ မပ္တံ ကဵုပ္ကဴ၊ လစိန် လှုဲလှာ်တအ် ဒှ်တမ်ရ",
