      "ပ္ဍဲခေတ် လောကဒဳဂျဳတေဝ် မ္ဂး သုတေသီတအ် စကာအေန်တာနက်၊ ဝဳကဳပဳဒဳယာမန် ကေုာံ ဆော့ဝဲ နာနာ သွက်ဂွံပကောံလိက်နိဿဲရ",
