      "စပ် ကုပရေင်ပညာမ္ဂး အခိင်မာံထောန်လာ အဝဲမံင်ဘာစိုပ် မံင်လဝ် ဘာတန်မူလ ကွာန်ဝါယာပ်အရာပ်ဗၟံက် ဇရေင်အစာ နာဲခွေး",
      "ပ္ဍဲကဵုဘဝပိုဲဏံ ဒးနွံကဵုပွမပြံင်သၠာဲညံင်ဂွံဒှ်အာလပါ်ခိုဟ်မာန်ဂှ် ဣဏံဟေင်ရပိုဲတံဒးပၠန်ဂတးဗွဲကိုပ်ကၠာအိုတ်ရ",
