      "ဗွဲကြဴ ဟိုတ်မတဝ်စၞေဟ် ကုသၟိင်ဗၟာတုဲ ဒးဒဴအာပဒတဴ ပ္ဍဲဍုင်မတ်မလီု သၟဝ်သၟိင်အင်္ဂလိက် မဂွံခပတိုန် နဒဒှ်စက္ကာဲရ",
      "ဒးၜက်ဗ္တံမ္ဂး လတူက္ၜင်ဂှ် မာတုဂါမ်တအ် ပါကၠုင်မံင်ကီုဟာ ဒဒှ် မာတုဂါမ်တအ်လေဝ် ပါကၠုင်မံင်ဟီုဂှ် ကလေင်သှ်ကဵုရ",
      "ကဝ်ဟေန် ညးတေအ် ပပၞညံင်ကဵု ဗၜူအိုတ်အစောန်တုဲ ညံင်ကဵု ညးတေအ် မုဟွံတီ မုဟွံကၠိုဟ် အရာညးတအ် မဟီုဂးဒၟံင်တအ်ဂှ်ရ",
      "ကြဴနူဂှ် လုပ်ကၠောန်ကမၠောန် ပ္ဍဲရုင်သၟိင်ဇၞော်ဓာတုဗေဒ နဒဒှ် တာလျိုင်ဂဒင်ဂြဳ ကေုာံ ဒုတိယတခဳဖိုင်ဖိုင်ပါ်ဓာတ်",
      "စနူ ဂိတုမာတ် ၂၇ ဂှ် ရဲကွာန်ကြေဝ်ဏာ ဗွဲမဂၠိုင် ဒြေပ်တိတ်လဝ် နူကွာန်တုဲ ပ္ဍဲကွာန်ဂှ် မၞိဟ် သှ်ေဒၟံင် ညိညဓဝ်ရ",
      "တင် မတၟေင် အိုတ် ဂှ် ကျာ်တြဲ ဇကု တိုင် ကွာ် ဗက် အာ လက္ကရဴ ရုပ် ကလာပ် မိဂေါတမဳ ပ္ဍဲ အခိင် ကၠောန် သဘင် ဈာပန ရ",
      "ဂကောံမၞိဟ်တြေံ မဒက်ပတန် ဍုင်ရးနိဂီုဂမၠိုင် ဒၞာဲရးနိဂီုဗၟာလၟုဟ်ဂှ် ဒှ် ဂကောံမၞိဟ် ဂကူမန် ကု ဂကူပျူ ၜါဂကူဏအ်ရ",
      "က္ဍိုပ်သ္ကိုပ်မၞိဟ်အရိုၚ်ဂှ်လေဝ် ဆက်ကွာဲကဵုတၟာဲတဲကုကိုဝ်လာန်ဗာတ်တုဲ ဂဥုဲတၞးဂှ် စိုပ်အာတိုက်ယူရောပ်ပတေံ ကီုရ",
      "ကောန်ဂကူဗုဒ္ဓဘာသာတံအဴ ကလၚ်အရေဝ်အပါဗှ်ေဒၠောံဗ္တောန်၊ တုဲပၠန် လ္ပကၠဟ်ထဝေၚ်ထောံ သီုကဵုမအရေဝ်မိယာဲဗှ်ေတံဂှ်ညိဏး",
