      "ပ္ဍဲမဟဂပ်ဝ်သၠးကၠေံဏီဂှ် မၞုံကဵုစၟတ်သမ္တီ သၠးကၠေံတုဲမ္ဂး၊ ပ္ဍဲမဟွံကၠေံလေၚ်အာဂှ် မၞုံကဵုစၟတ်သမ္တီကၠေံလေၚ်မ္ဂး",
      "လညာတ် ဏအ်ဝွံ အာရီုစွံ လတူ ပရေင်မင်မဲ သစ္စာ အကြာ မၞိဟ် ၜါ ကေုာံ ပရေင်ဝေင်ဒစး ပွမကဵု ဒဒိုက် စိုတ် ကု ညးတၞဟ် ရ",
      "ပ္ဍဲလိက်လလောင်တြးဂှ် ဗၟံက်ထ္ၜးလဝ် ဂကောံမဒှ်ဂုဏ်ဖိုလ် ကုအလုံဂကူမန်မွဲ ညံင်ဂွံမံက်ဂတဝ်တိုန်ဂှ် သ္ဒးဒက်ပ္တန်အာ",
      "ကျာ်ဣသိယဵု ကဵု ဒဵုဖျဂျဳ ညံင်ဂွံကြပ်ဂှ် ညံင်ရဴ မဒှ်ဟွံမာန်ကီု ဘဝအဲ ကဵု ဖူဂျဳလေဝ် သာ်လဵုမှ ကြပ်ညးသကအ် ဟွံမာန်ရ",
      "ဗီုရုပ် ဗိုလ်တေန်ဥူ မဗ္ဂိန်ကဵုဒါန်သ္ၚာ ကုကျာ်ဇၞော်ဂှ် မွဲအခိင်တေအ် ထ္ၜးစွံလဝ် ပ္ဍဲ ဘာထံင်ကှ်ေဂှ် သၞာံဗွဲမလအ်",
      "အမတ် တအ် ဏအ် ဂှ် ဟွံဒုင် တဲ လတူ ပရေင် သီ အဝဵု ဏအ် တုဲ ညးတအ် ဂစာန် ဒက်ပ္တန် စၠတ်ထဝ် မွဲ ကဏ္ဍ ဍောတ် ကိုပ်ကၠာ ရ",
      "ပတ္တိဒါနကုသဵု ဖဵုဇကုမကၠောန်ပ္တုဲလဝ်ဂမၠိုၚ် ပွမပါ်ပရအ်ဇိုန်ပိုန်ကဵုညးသ္အာၚ်မ္ဂးဂှ် အိုတ်အာ, ယအ်အာရောင်ဟွံမွဲရ",
      "နဳဗာန်ထာန်ဒိပ် ဗနိပ်အယော၊ ၜိုတ်စိုတ်လောန်ရော ဇၞးဆောမစ္စု၊ လၟုဟ်အံက်ဂၞဴ ပ္တေဟ်ဗြဴဣလု၊ ကျပၞာန်မစ္စု ဒဵုဗျုရရော",
      "ကၠာတေံဏအ် ကောန်ဂကူမန်ဍုၚ်ပလိုတ်ဏအ် စၟဳမံၚ်နွံမွဲဂှ် သေံမန်တံ တိတ်ကၠုၚ်ဏောၚ်၊ သေံမန်တံ တိတ်ကၠုၚ်ဏောၚ်စၟဳမံၚ်ရ",
      "အဒိဿထ၊ စိုန်စၞောန်ထ္ၜးတဴရ ခမဳတံ၊ ဗမၞးအိန်တန်ဒၟံၚ်တုဲ သၟိက်ဟီုဂလာန်ပဋိသန္ဓာရတုဲ ဂါထာသာ်ဝွံ သၟိၚ်အိန်သ္ဂးပၠန်ရ",
      "ယဝ်ရ လေမ်မာ ဟွံချိုတ်ပၠိုတ် မ္ဂး၊ မအရေဝ် တအ် ဍေံ ထုဲနှဴ အာ တုဲ ညးလ္ၚတ် တအ် ဂၠာဲ အဓိပ္ပါယ် ဝါတ်ဂါတ် အာ မာန် ရ",
      "ညံင်ရဴသာ်ဂှ်ကီု သဘဴဓရ် သဟဇာတဝွံ ဓရ်ဟိုတ် ကေုာံ ဓရ်ဖိုလ်တအ် ကတဵုဒှ်ကၠုင် မွဲခဏဓဝ်တုဲ ထံက်ပင်ဗိုင်ရီုရေင်သ္ကအ်ရ",
      "ဂကူမန်၊ ဂကူဗၟာ၊ ကေုာံ ဂကူ ကောန်ဍုင်အရင် တၞဟ် တအ် လေဝ် ပလံင် ဇွောအ်မ စၞစ သွက် ကွးဘာ တအ် မနွံ ပ္ဍဲ ကျာ်လ္ဂုင် ရ",
      "ပ္ဍဲ အနာဂတ်၊ လဒက်ပတန် ဂကောံ ဝန်ဇၞော် ဏအ် မာန် ဆက် ပြံင်လှာဲ အာ အတိုင် အကာဲအရာ ခေတ် ကေုာံ ပရေင်နွံပၟိက် ဍုင် ရ",
      "စပ်ကဵုသၞောဝ်ဏအ် ပတိုန်ထ္ၜးလညာတ် ကေုာံ ကလးဗီုမဗၟံက်ရုပ်ရဴကမၠောန်တအ်တုဲ သီုဖအိုတ် ဒးကေတ် အခိင် ပွိုင် ၆၀ မိနေတ်",
      "ဂကူမန်တအ် ဂွံပါဗက်လ္တူစၚ်ဂၠးတိခေတ်ဂလိုဗယ်ဏအ်မာန် ဒးလးဂၠံၚ်တၟိ လညာတ်တၟိ ကသပ်တၟိ ဒးပြံၚ်လှာဲတြေံကဵုတၟိမာန်ရောၚ်",
      "လိက်ပရေင် ဏအ်ဝွံ သ္ၚေဝ်ဂၠေပ် လဝ် ပရူပရာ ထရောန် နကဵု လညာတ် ဝင်၊ ဂကူ၊ ကွတ်ပညာ၊ ကေုာံ လွပ် ဍေဟ်တအ် ဗွဲမအလုံစုံ ရ",
      "ဂရၚ်ပတီဂလာန်ဝွံတုဲမ္ဂး လ္ၚောဝ်သ္ပဝတ် တဳလပိုဉ်မဟာမောဂ္ဂလာန်တုဲ သ္ပရှေ်သှေ်ရဴဂဴကၠာ ကၠေံဗ္ဒန်အာ ပ္ဍဲဌာန်ဂှ်ဟေၚ်ရ",
      "သီုဟွံဂိယြ မၞုံကဵုစၟတ်သမ္တီဂိယဲဒှ်တုဲ တၞဟ်နဖဵုသွက်ဇကု အာတ်တဴဘောဇိုန်မပြဲပြဲဂမၠိုၚ်တုဲ စမ္ဂး၊ ဒးအာပတ်ပါဲစိုတ်ရ",
      "အပ္ဍဲသၞေဟ်အဒေါဝ်ဝွံ အရာပ်ဗဒဝ်ဇၞော်နွံဒၟံၚ်တုဲ အခိၚ်ကာညးတအ်စွံဂၠုၚ်မ္ဂး ဇုက်ဂၠုၚ်တအ်ဂှ် ဒက်ကဵုတၞံဗဒဝ်တအ်အိုတ်ရ",
      "ဟိုတ်ဒှ်သာ်ဂှ်ရ ကမ္မဝိပါကော န်ဗီုကံမကဵုဖဵု ဨတ္တကော ဗၞတ်ဆဝွံဟေၚ်ရဟီုဂှ် အစိန္တိယော ပိုၚ်ခြာတုဲ စိုန်ဂပ်ဝ်ချပ်ရ",
