      "ဘာသာအေန်ဒဝ်နဳယှာဝွံ ကလိဂွံလဝ် သြဇာနူဘာသာနာနာ မပ္တံကဵု ဘာသာသံသကြိုတ်၊ ဘာသာအာရဗဳ၊ ဘာသာဟဝ်လာန် ကေုာံ ဘာသာအေန်ဂလိက် ရ",
