      "ပ္ဍဲကဵု ပရေင်သိပ္ပံ ကေုာံ နှိုတ်မၞိဟ်မ္ဂး အခိင်ဝွံ ဒှ် သဇိုင် သွက်ဂွံ ဗၜတ် လလအ်၊ အခိင်ကာလ ကေုာံ ပြံင်လှာဲဂမၠိုင် ရ",
