      "ဟီုကၠးကၠးမ္ဂး ကုဍုင် မထပက်လဝ် စၟတ်တဲ ပ္ဍဲလိက်ကသုက်သက္ကုအနုလက်ကၠိုက်တအ်ဂှ် အခေါင်ကၠောန်ဗဒှ်ပတိုန် လွဟ်နျူကလဳယျာ ဟွံမဲရ",
