      "သိုင်ခၞံဘာကုဋ် ဟွံမွဲကဵုပရိုက်ဘဲ မၞုံကဵုဥပစာ မွဲသ္ပဝ်ကွဳအိုတ်မ္ဂး၊ ကုခမဳသိုင်ခၞံဘာကုဋ်ဂမၠိုင် ဒးအာပတ်ဒုက္ကဋ် ၜါလစုတ်ရ",
