      "အမေရိကန်ပြည်တွင်းစစ် အတွင်းတွင် အနောက်ဗာဂျီးနီးယား ပြည်နယ်သည် ဗာဂျီးနီးယားမှ ပြည်နယ်တစ်ခု အဖြစ် သီးသန့် ခွဲထွက် ခဲ့သည်",
      "လိက်တၟအ် တအ်ဝွံ ဆက် ဒှ် ဒၟံင် ပရူပရာ မလ္ၚတ် သုတေသန ဇၞော်အိုတ် သွက် တၠပညာ ဝင်၊ အက္ခရ်၊ ကေုာံ ဗုဒ္ဓဘာသာ အလုံ ဂၠးတိ ရောင်",
      "ကွာန်ဇၞော်မွဲ သၟိၚ်ကဵုကောန်ဗြဴရ၊ နအခေါၚ်ကွာန်ဂှ် ဇၟာပ်ကိစ္စအိုဿီု ကောန်ဗြဴဂွံပ္တုဲတဴရ၊ ပ္ဍဲကိုပ်ကၠာဂှ် ဒှ်ညံၚ်နဲသာ်ဏံရ",
