      "ကောန်ပၞာန်ဗၟာ နကဵု ဒြဟတ်ၜိုတ် ၃၀ တၠ ကၠုင်ဗတိုက် ပ္ဍဲ ကွာန်ဓမ္မသတုဲ ဒှ် ပေါဲဗတိုက် ကုဒပ်ပံင်ကောံ မနွံ ပ္ဍဲကွာန်ဓမ္မသဂှ်ရ",
      "လိက်ပတ်စပ်ကဵုပရိယတ် လ္ပာ်ကတ်ဗ္တောန်ပါဠိအဋ္ဌကထာ ပိဋကတ်ဂှ် စၟဳရံၚ်အာအဆက်ဟွံဆဵုတုဲ အဆက်မိက်ဂွံပိုတ်အာညိ ပိုဲမ္ဒးတၟော်ဆကေတ်",
