      "လၟုဟ်မ္ဂး ဗဳဇဗေဒ ဂှ် ပါလုပ် ပ္ဍဲကဵု ကဏ္ဍ အဓိက သွက် ပရေင်ဂဥုဲ၊ ပရေင်တဵုလွဳ၊ ကေုာံ ပရေင်လ္ၚတ် ဇဳဝဗေဒ ဇၞော်မောဝ် အလုံသီုဖအိုတ်ရ",
      "ညး ပြံင်လှာဲ ဍုင်ဗၟာ မနွံကဵု အလားအလာ ခိုဟ် ပ္ဍဲ အာရှ ဂှ် ညံင် ဂွံ ဒှ် အာ ဍုင် ဒိုက်ဂတ်၊ မနွံကဵု ပၞာန် အပ္ဍဲ ဍုင် ဗွဲမလအ် လ ရ",
