      "တၠဂုဏ်အဇ္ဇလေဝ် စိုတ်ဓာတ်ဆာန်ဂကူ ပေင်ကၟိုဟ်ဒၟံင် ဗီုပကတိတြေံတေအ်ဏီတုဲ ကမၠောန်ပရဟိတ ဒတုဲဖိုလ်သွက်ဂကူဂှ်ဟေင် ဆက်ရေင်တၠုင်အာပၠန်ရ",
