      "ဝင် ဍုင် ကဳယေဗ် ဝွံ ဍေံ ဇြိုဟ်နက် ကေုာံ ဇၞော်ကဵုဇြဟတ် ဗွဲမလောန် တုဲ ဍေံ ဒှ်လဝ် ဗဟဵု သွက် ပရေင် ပြံင်လှာဲ ဝင် မဂၠိုင် ကု အလန် ရ",
