      "ပတန်ဍုၚ်တုဲ ရသိဂှ် အာတ်တၞောဝ်သၟိၚ် သွက်ဂွံပကၚ်ရၚ်ဍုၚ် ဇရေၚ်သၟိၚ်စက္ကဝတ္တိရာဇာ မဒှ်ဨကရာဇ်ဍုၚ်ဒွါရဝတဳ မပဒတဴ ပ္ဍဲဍုၚ်ဇၞော်လပ်ဗူရဳရ",
