      "ယွံခမဳတအ် ကုခမဳ မဍိုက်ပေၚ်တဴ ကေုာံအၚ်္ဂဂမၠိုၚ် မသုန်ပြကာဝွံ ဟွံထေက်ကဵု လလမ်ကၠေံ ဥက္ခေပနဳယကမ် မသ္ပလဝ် ဟိုတ်ပွမဟွံမၠာ်သ္ၚေဝ်အာပတ်ရ",
