      "ဒၞဲါမာံဂံင်သာဲ မအောပ်ဗ္ဒဒၟံင်သၟဝ်တမ်မြာင်ဂှ် ဗွဝ်အိက်ဂၠဴကှ်ကှ် နွံဒၟံင်တုဲ ပသဒၟံင် သၟူအိက်ဂၠဴကီု ဒးမာမပ်မံင်ဇရေဝ်ဗွဝ်အိက်ဂၠဴဂှ်ရ",
