      "ပၞာန်ဂၠးတိ အလန်ပထမ အာစိုပ်ဒတုဲတုဲ ကာလကလေင်သ္ၚေဝ်ဂၠေပ် သၞောတ်ဂၠးကဝ်တၟိဂှ်တုဲဂှ် ရုပ်ရဴကမၠောန် ဒက်ပတန် ရုင်ဗစာဂၠးတိဂှ် စမံက်ကၠုင်ရ",
      "နာဲဖဝ်နုမ် ကဵု နာဲဖဝ်ယုံ ညးၜါ ဝါသနာ နွံ ပ္ဍဲကွိင်ကွိုက် ဗွဲမလောန်တုဲ အာဗ္တောန် ကွတ်ကွိင်ကွိုက် ဇရေင် ဦးပြာလောင် ပ္ဍဲဍုင်မတ်မလီုရ",
