      "ဆဂး အဇုန ဟွံဒုင်တဲ ဥတ္တရာ နဒဒှ် သမ္ဘာ ဟိုတ်နူကဵု ညး ဒှ် လဝ် အစာ လှ်ေဒွက် သွက် ဥတ္တရာ တုဲ ညး ဆာန် ဥတ္တရာ တုပ် ညံင် ကောန် ဇကု မွဲ ရ",
      "သွက် အနာဂတ် ကောန်မၞိဟ် ဂှ်၊ ဝင် ထ္ၜးကဵု ဒဒှ်ရ ကောန်မၞိဟ် တအ် နွံကဵု အစောံသတ္တိ မမာန် ပြံင်လှာဲ ကေုာံ ဖန်ဗဒှ် နည်းပညာ တၟိ လၟိုန် ရ",
      "ဗဝ်သဝါနာဝွံ ဒှ်ဍုင် မနွံကဵု ပရေင်ဍုင်ကွာန် ဒဳမဝ်ကရေသဳ မညိင်ဝတ်အိုတ် ကေုာံ ပရေင်ပိုန်ဒြပ် မဇၞော်မောဝ်ပြဟ်အိုတ် မွဲပ္ဍဲတိုက်အာဖရိကရ",
      "ပ္ဍဲဇဂိုဏ်ဝွံ အခိုက်ဂၠိုၚ်က္ဍၚ်သန်၊ ကရီုသုဓနု၊ ကရီုအာန်ဇုနာန်၊ ရာဇလတိုၚ်ကောန်၊ ဘိမာလတိုၚ်ကောန််၊ အခိုက်သာ်ဝွံ တိတ်နူဇဂိုဏ်ဖအိိုတ်ရ",
      "ဝတ္ထုမဂပ်ဝ်သၟိတ်ဂးရတ် မ္ဂးဂှ် အရပ်စပ်သုၚ်စောဲအပ္ဍဲကီု အရပ်စပ်သုၚ်စောဲမ္ၚးမၞိဟ်ဂမၠိုၚ်ကီုရောၚ်၊ ဣဝွံတုန် ဝတ္ထုမဂပ်ဝ်သၟိတ်ဂးရတ်မ္ဂးရ",
