      "နာဲတိင်ဇြာန် ကဵု ဥူထောန်ယျ ညးၜါ ဗွဲကိုပ်ကၠာဂှ် ၜိုန်ရ စိုတ်တုပ်ကီုလေဝ် စိုပ်အပ္ဍဲဂှ်ဗက် နကဵု ဥူထောန်ယျ ဂစာန်တက်ဂစိုတ် နာဲတိင်ဇြာန်",
      "ၜိုန်ရ လညာတ် တၞဟ်ခြာ ကီုလေဝ်၊ အစာသုတေသန သီုဖအိုတ် တုပ်စိုတ် ဒဒှ်ရ မလိက်ပျူ ဝွံ ဒှ် မလိက် တြေံအိုတ် မစကာလဝ် ပ္ဍဲကဵု တိဍာ် ဍုင်ဗၟာ ရ",
      "မၞိဟ်ယၟုပြာကတ်ဂမၠိုင်ဂှ် နာဲဟံသာတ္ၚဲဏအ်၊ နာဲတၠညး၊ နာဲဆာန်တိ၊ နာဲအံက်ပိုင်၊ နာဲသက်လောန်၊ အစာသဵုတာန်၊ နာဲသဳဟ၊ နာဲဝင်တၟိ၊ မိလျိုင်မန်",
      "ပ္ဍဲပွီပွိုၚ်အရှာံကျာ်စေတဳလ္ဂုၚ်ကီု သီုကဵုကျာ်စေတဳမံက်တဴဂှ် တၞံရိုက် တၞံတာ ကှေ် အဂၞု အနာၚ် မြာၚ် ကြုက် ပၞဟ်ဗွဲမဂၠိုၚ် တဵုလဝ်အိုတ်ရ",
