      "ၜဳဝွံ ဟွံသေင်ဆဍာ်မဇွောဝ်ဝေင်၊ ဆဂး ဒှ်ဒၞာဲမဖန်ဗဒှ်ကဵု တိဗ္ၚမနွံကဵုဆီမြဟ်၊ ဒၞာဲမပဒတဴသတ်ဍာ်ဂမၠိုင် ကေုာံ ဂၠံင်တရဴပရေင်ဆက်ဆံင်မၞိဟ်တအ်ရ",
      "ပ္ဍဲလပါ်ဒိုဟ်အဂၞဲ ကြုၚ်မၞုံယၟုသလ္လဝတဳ နွံရ၊ လပါ်မ္ၚးနူကြုၚ်သလ္လဝတဳဂှ်တုန် ဇနပိုဒ်ပစ္စန္တရးဂမၠိုၚ်မ္ဂးရ၊ လပါ်အပ္ဍဲတုန် မဇ္ၛိမရးမ္ဂးရ",
      "ၜိုန်ရ ညး သၠးဂၠံဂဝ် ပ္ဍဲ ဒေသ တၞဟ် ကီု လေဝ်၊ ညး ဝွံ ဒှ် မၞိဟ် မၞုံ ကု ဍာ်ရိုဟ် ပရေင် အုပ်ကွပ် ကေုာံ အစောံစရာဲ ကွတ် ပၞာန် ဗွဲမလောန် ရ",
