      "လိက်ပရေင် ဏအ်ဝွံ သ္ၚေဝ်ဂၠေပ် လဝ် ပရူပရာ အက္ခရ် ဂျာဗာ နကဵု လညာတ် ဝင်၊ လဒက်ပတန် အက္ခရ်၊ ကွတ်ပညာ၊ ကေုာံ ပရေင်မင်မဲ ပ္ဍဲ ခေတ်တၟိ ဗွဲမလှဲလး ရ",
