      "လိက်ပရေင် ဏအ်ဝွံ သ္ၚေဝ်ဂၠေပ် လဝ် ပရူပရာ ယဲမလဳရဳယျာ နကဵု လညာတ် ဝင်၊ လညာတ် သိပ္ပံ၊ စၟယဲ၊ ပရေင်လွဳလွတ်၊ ကေုာံ သၞောတ် စဵုဒၞာ တအ် ဗွဲမလှဲလး ရ",
      "သွက်ပုၚ်မွဲဗုၚ် လ္ပဒုၚ်လ္ပဍိက်ပၠက်ညးကလက်ဂကူဇကုညိ၊ ဒုၚ်သ္ပဍိက်ညးမ္ဂး ညးဇြဟတ်ဇၞော်သၠုၚ် ဂကူဇကုဒးဒုၚ် ဍုၚ်ဇကုဒးကၠေံ ဘဝဂကူဇကု ဒးပရေအ်အာရောၚ်",
