      "လိက်ပရေင် ဏအ်ဝွံ သ္ၚေဝ်ဂၠေပ် လဝ် ပရူပရာ အာန်ကောဝ်ဝတ် နကဵု လညာတ် ဝင်၊ ပရေင်သြိုင်ခၞံ၊ ကွတ်ဗဒက်၊ ကေုာံ ဖဵုသက်ရောက် လတူ ခေတ်တၟိ ဗွဲမလှဲလး ရ",
      "သေပ်တေမ်ဗါ ၁၂ ဂှ် ကၠောန်ၜိုတ် ပကုသဵု ပ္ဍဲကဵု ဘာဇၞော် ကွာန်မုဟ်ဒုန်၊ တကအ်ခၟိုင်တုဲ ပ္ဍဲတ္ၚဲဂှ် သီုကၠောန် အစဳအဇန်ဗၞုဟ်ဂုဏ် နာဲထောန်ဝဵုကီုရ",
      "ပွမစုတ် ပ္ဍဲစရင်ဏအ်ဂှ် ဍေံဟွံသေင် ပွမကဵုဒဏ်ရ၊ ဍေံဒှ် လၟေင်ကမၠောန် သွက်ဂွံ ကော်ဘိက် အရီုအဗင် နူဂၠးကဝ် သွက်ဂွံ ပြဟ်ပြဟ် ကလေင်ပလေဝ် ဒတန်ဂှ်ရ",
      "ဟွံမွဲကဵု ပွမ္ဒးတွံအ္အဇ္ၚးဂှ် ဒှ်ဂုဏ်မရနုက်ကဵုၜါရ၊ ဂလာန်ဂှ်ဍာံစၟတ်ရ၊ တွံၚးတးကဵုဒှ် ဟွံတွံၚးတးကဵုဒှ် ဒှ်အယာံမာတ် ဂွံသ္ပဒ္တဴ ဗွဲတသိုက်ဟေၚ်ရ",
      "ပ္ဍဲအခိၚ်ဂှ် တဳလပိုဉ်အာနန္ဒ သၠောံရုၚ်လတက်သ္ၚာမသာဂမၠိုၚ်တုဲ လုပ်ဂ္ၚေၚ်ပိဏ္ဍပါတ် အပ္ဍဲကွာန်ရ၊ ဟိုတ်နူကျာပလက်သကိုပ်ဂမၠိုၚ် သၠိုက်တိုန်အိုတ်ရ",
      "ၜိုန်ရ နက္ခတ္တဗေဒ ဂှ် လ္ၚတ် ပရူ စက္ကဝါ ဇၞော် ကီုလေဝ်၊ ပ္ဍဲကဵု သိပ္ပံ တိ မ္ဂး ဍေဟ် လ္ၚတ် ရံင် အဆက်အစပ် အကြာ ဂြိုဟ်တိ ကဵု တ္ၚဲ ကေုာံ ဂိတု ရ",
      "ပ္ဍဲအခိၚ်ဂှ် တဳလမၞုံပိုဉ်ကျာ်တြဲ ပ္ဍဲအခိၚ်နူဂယး ဗိုက်ပလေဝ်ပလေတ်သ္ၚာတုဲ သီုမထ္ၜဂိုၚ်ရပ်ကေတ်ဗဗေၚ်သ္ၚာဂှ် က္ညပြာပ်အာသ္ၚိနန် ကောန်သၟိၚ်ဗောဓိရ",
      "ဨကရာဇ်ဗြဴဗညာထဴမိစဴဗု ပတၠသဒ္ဒါမလျုၚ်သ္ဍိက်ရတ်ပိပြကာ ပ္ဍဲသာသာသနာကျာ်တုဲ နိမန်ခမဳသၚ်မွဲမွဲတ္ၚဲ မသုန်မသုန်ကၠံ ကဵုဒါန်ပိဏ္ဍပါတ်လၟိုန်တ္ၚဲရောၚ်",
      "သ္ၚေဝ်ဂၠေပ်နကဵုမတ်စိတ္တဗေဒမ္ဂး ယဝ်ရညးတအ်စှ်ေစိုတ် ဒဒှ်ရၝောအ်ဂှ် ဒှ်အရာမယုတ်သဝ်မ္ဂး ဗီုလဵုလေဝ် ညးတအ်ဂွံဆက်ချူအာ အတိုၚ်ဂှ် ဒှ်ကၠုၚ်ဟွံမာန်ရ",
      "ဍုၚ်ကိုၚ်ရဝ်ဂှ် နွံကဵု ဝၚ်အတိက် ဗွဲမဇြိုဟ်နက်တုဲ ဒယှ်တမ္ညဝ်ဒၟံၚ် နကဵု ဒတန် ယေန်သၞာၚ်၊ ဘာသာ၊ ကေုာံ ပရေၚ်ပိုန်ဒြပ် ခေတ်တမၠာ ကေုာံ ခေတ်တၟိ ရ",
